package com.dreamcore.workspace;
import com.dreamcore.workspace.forwarding.*;
import com.dreamcore.workspace.document.*;
import com.dreamcore.workspace.conversation.*;
import com.dreamcore.workspace.material.*;
import com.dreamcore.workspace.identity.*;
import java.util.*;
import java.util.concurrent.*;
import java.net.*;
import java.net.http.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"dreamcore.tasks.enabled=true","dreamcore.tasks.agent-mode=verification","dreamcore.tasks.initial-delay-ms=3600000","dreamcore.knowledge.enabled=false"})
class ForwardingIntegrationTest {
 @Autowired ForwardingService forwards;@Autowired DocumentPublicationService publications;@Autowired DocumentService documents;@Autowired ConversationService conversations;@Autowired AgentTaskService agents;@Autowired MaterialService materials;@Autowired JdbcTemplate db;@Autowired PasswordEncoder passwords;@Autowired com.dreamcore.workspace.lifecycle.MaterialLifecycleService lifecycle;@Autowired com.dreamcore.workspace.lifecycle.MaterialCleanupService cleanup;@LocalServerPort int port;
 UUID tenant,sender,reader,admin,source,space,document;DocumentPublicationService.Publication copy;
 @BeforeEach void setup(){tenant=UUID.randomUUID();sender=UUID.randomUUID();reader=UUID.randomUUID();admin=UUID.randomUUID();source=UUID.randomUUID();space=UUID.randomUUID();for(UUID a:List.of(sender,reader,admin))db.update("INSERT INTO accounts(id,email,display_name,password_hash) VALUES (?,?,?,?)",a,a+"@forward.test",a.equals(sender)?"合成发送者":"合成接收者",passwords.encode("synthetic-forward-password"));db.update("INSERT INTO tenants(id,name) VALUES (?,'站内转发合成企业')",tenant);for(UUID a:List.of(sender,reader,admin))db.update("INSERT INTO tenant_memberships(tenant_id,account_id,role) VALUES (?,?,?)",tenant,a,a.equals(admin)?"TENANT_ADMIN":"MEMBER");db.update("INSERT INTO workspaces(id,tenant_id,owner_id,name,kind) VALUES (?,?,?,'私人来源','PERSONAL'),(?,?,?,'独立企业副本','SHARED')",source,tenant,sender,space,tenant,admin);db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id,can_maintain) VALUES (?,?,?,true),(?,?,?,false)",tenant,space,sender,tenant,space,reader);var detail=conversations.submit(sender,tenant,null,source,UUID.randomUUID(),"私人提示不可出现在转发", "AGENT");var t=conversations.claim();agents.finish(t,new AgentResult("1.4","0.12.0",t.id(),t.token(),"AGENT","verification","synthetic-forward","合成文稿正文",List.of(),List.of(),List.of(),1,null,List.of(),List.of(),List.of()));document=documents.create(sender,tenant,detail.conversation().id(),t.id(),null,UUID.randomUUID()).document().id();documents.save(sender,tenant,document,UUID.randomUUID(),1,"明确发布的企业成果","合成文稿正文");copy=publications.publish(sender,tenant,document,2,UUID.randomUUID(),space,null,null,null,"docx",true);}
 @AfterEach void releaseOwnTasks(){if(tenant!=null)db.update("UPDATE conversation_tasks SET status='CANCELLED' WHERE tenant_id=? AND status IN ('QUEUED','RUNNING')",tenant);}
 void denied(int code,Runnable r){assertEquals(code,assertThrows(IdentityException.class,r::run).status);}
 ForwardingService.Send input(UUID key,List<UUID> recipients){return new ForwardingService.Send(key,copy.id(),copy.materialVersionId(),recipients,"请核对这份已发布成果");}
 ForwardingService.Batch send(){return forwards.send(sender,tenant,input(UUID.randomUUID(),List.of(reader)));}
 @Test void transferPreservesExactIndependentCopyAndAcceptedIsNotOpened(){var people=forwards.recipients(sender,tenant,copy.id(),copy.materialVersionId(),"",0,20);assertEquals(List.of(reader),people.items().stream().map(ForwardingService.Person::id).toList());denied(404,()->forwards.recipients(admin,tenant,copy.id(),copy.materialVersionId(),"",0,20));var b=send();assertEquals("ACCEPTED",b.recipients().getFirst().state());assertNull(b.recipients().getFirst().openedAt());var inbox=forwards.inbox(reader,tenant,0,20);assertEquals(1,inbox.items().size());assertEquals(copy.materialVersionId(),inbox.items().getFirst().source().materialVersionId());assertEquals(copy.sha256(),ObjectStore.sha256(materials.download(reader,tenant,space,copy.materialId(),copy.materialVersionId()).bytes()));assertEquals("ACCEPTED",forwards.batch(sender,tenant,b.id()).recipients().getFirst().state());String text=new tools.jackson.databind.json.JsonMapper().writeValueAsString(inbox);assertFalse(text.contains(document.toString()));assertFalse(text.contains("私人提示"));assertFalse(text.contains("documentId"));assertTrue(forwards.inbox(admin,tenant,0,20).items().isEmpty());}
 @Test void sourcePrivateCleanupDoesNotRevokePublishedCopyButPublishedCleanupScrubsForwardNote(){var b=send();UUID task=db.queryForObject("SELECT source_task_id FROM private_documents WHERE id=?",UUID.class,document);db.queryForList("SELECT scrub_lifecycle_object('TASK',?)",task);assertEquals(1,forwards.inbox(reader,tenant,0,20).items().size());lifecycle.act(sender,tenant,space,"MATERIAL",copy.materialId(),UUID.randomUUID(),0,"TRASH");assertTrue(forwards.inbox(reader,tenant,0,1).items().isEmpty());assertFalse(forwards.inbox(reader,tenant,0,1).hasMore());db.update("INSERT INTO governance_capabilities(tenant_id,account_id,workspace_id,capability,granted_by) VALUES (?,?,?,'LIFECYCLE_PURGE',?)",tenant,sender,space,admin);lifecycle.act(sender,tenant,space,"MATERIAL",copy.materialId(),UUID.randomUUID(),1,"PURGE");var job=cleanup.claim();assertNotNull(job);for(UUID o:cleanup.pending(job)){cleanup.remove(o);cleanup.removed(job,o);}cleanup.finish(job);assertEquals("",db.queryForObject("SELECT note FROM publication_forward_batches WHERE id=?",String.class,b.id()));assertTrue(db.queryForObject("SELECT scrubbed FROM publication_forward_batches WHERE id=?",Boolean.class,b.id()));}
 @Test void oneUnavailableReceiverRejectsWholeBatchAndAdminDoesNotGainReadAccess(){denied(404,()->forwards.send(sender,tenant,input(UUID.randomUUID(),List.of(reader,admin))));assertEquals(0,db.queryForObject("SELECT count(*) FROM publication_forward_batches WHERE tenant_id=?",Integer.class,tenant));denied(404,()->forwards.send(admin,tenant,new ForwardingService.Send(UUID.randomUUID(),copy.id(),copy.materialVersionId(),List.of(reader),"")));}
 @Test void sameRequestIsAtomicAndNeverAppendsNewlyGrantedMembers()throws Exception{var request=input(UUID.randomUUID(),List.of(reader));ForwardingService.Batch b;try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->forwards.send(sender,tenant,request));var other=pool.submit(()->forwards.send(sender,tenant,request));b=a.get(10,TimeUnit.SECONDS);assertEquals(b,other.get(10,TimeUnit.SECONDS));}db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id) VALUES (?,?,?)",tenant,space,admin);assertEquals(b,forwards.send(sender,tenant,request));assertTrue(forwards.inbox(admin,tenant,0,20).items().isEmpty());denied(409,()->forwards.send(sender,tenant,input(request.requestId(),List.of(reader,admin))));assertEquals(1,db.queryForObject("SELECT count(*) FROM publication_forward_receipts WHERE batch_id=?",Integer.class,b.id()));}
 @Test void onlyRecipientOpenRecordsOneTimeAndSenderViewsNeverOpenIt(){var b=send();UUID receipt=b.recipients().getFirst().receiptId(),key=UUID.randomUUID();forwards.batch(sender,tenant,b.id());denied(404,()->forwards.open(sender,tenant,receipt,UUID.randomUUID()));assertNull(db.queryForObject("SELECT opened_at FROM publication_forward_receipts WHERE id=?",java.sql.Timestamp.class,receipt));var opened=forwards.open(reader,tenant,receipt,key);assertEquals("OPENED",opened.state());assertNotNull(opened.openedAt());assertEquals(opened,forwards.open(reader,tenant,receipt,key));assertEquals(opened.openedAt(),forwards.open(reader,tenant,receipt,UUID.randomUUID()).openedAt());}
 @Test void recipientAndSenderRevocationHideBeforePaginationAndOldOpenCannotBypass(){var b=send();UUID receipt=b.recipients().getFirst().receiptId(),key=UUID.randomUUID();forwards.open(reader,tenant,receipt,key);db.update("DELETE FROM workspace_members WHERE workspace_id=? AND account_id=?",space,reader);assertTrue(forwards.inbox(reader,tenant,0,1).items().isEmpty());assertFalse(forwards.inbox(reader,tenant,0,1).hasMore());denied(404,()->forwards.open(reader,tenant,receipt,key));assertFalse(forwards.batch(sender,tenant,b.id()).recipients().getFirst().currentlyAccessible());db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id) VALUES (?,?,?)",tenant,space,reader);db.update("DELETE FROM workspace_members WHERE workspace_id=? AND account_id=?",space,sender);assertTrue(forwards.inbox(reader,tenant,0,1).items().isEmpty());}
 @Test void newerPublicationNeverChangesForwardedVersionAndOwnerScopeScrubKeepsMinimalReceipt(){var b=send();documents.save(sender,tenant,document,UUID.randomUUID(),2,"新版本","后续发布的新内容");var newer=publications.publish(sender,tenant,document,3,UUID.randomUUID(),space,null,copy.materialId(),1,"docx",true);assertNotEquals(copy.materialVersionId(),newer.materialVersionId());assertEquals(copy.materialVersionId(),forwards.inbox(reader,tenant,0,20).items().getFirst().source().materialVersionId());assertEquals(1,db.queryForObject("SELECT scrub_forwarding_scope(?,?)",Integer.class,tenant,sender));assertTrue(forwards.inbox(reader,tenant,0,20).items().isEmpty());assertEquals(1,db.queryForObject("SELECT count(*) FROM publication_forward_receipts WHERE batch_id=?",Integer.class,b.id()));}
 @Test void publicApiRequiresSessionAndCsrf()throws Exception{var http=HttpClient.newHttpClient();var response=http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1/tenants/"+tenant+"/forwarding/inbox")).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(401,response.statusCode());var post=http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1/tenants/"+tenant+"/forwarding/batches")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{}")).build(),HttpResponse.BodyHandlers.ofString());assertEquals(403,post.statusCode());}
 final class Client {final tools.jackson.databind.json.JsonMapper json=new tools.jackson.databind.json.JsonMapper();final HttpClient http=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();HttpResponse<String> request(String method,String path,Object body,boolean csrf)throws Exception{var req=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).header("Content-Type","application/json");if(csrf){var token=json.readTree(request("GET","/api/v1/auth/csrf",null,false).body());req.header(token.get("headerName").asString(),token.get("token").asString());}return http.send(req.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}void login(UUID id)throws Exception{assertEquals(200,request("POST","/api/v1/auth/login",Map.of("email",id+"@forward.test","password","synthetic-forward-password"),true).statusCode());}}
 @Test void realAuthenticatedHttpAcceptanceConflictAndRevocation()throws Exception{Client client=new Client();client.login(sender);String path="/api/v1/tenants/"+tenant+"/forwarding";UUID key=UUID.randomUUID();var input=input(key,List.of(reader));var accepted=client.request("POST",path+"/batches",input,true);assertEquals(201,accepted.statusCode(),accepted.body());assertTrue(accepted.headers().firstValue("cache-control").orElse("").contains("no-store"));var body=client.json.readTree(accepted.body());assertEquals("ACCEPTED",body.get("recipients").get(0).get("state").asString());assertEquals(body,client.json.readTree(client.request("POST",path+"/batches",input,true).body()));var conflict=client.request("POST",path+"/batches",new ForwardingService.Send(key,copy.id(),copy.materialVersionId(),List.of(reader),"different"),true);assertEquals(409,conflict.statusCode());assertEquals("1.0",client.json.readTree(conflict.body()).get("contractVersion").asString());assertEquals("IDEMPOTENCY_CONFLICT",client.json.readTree(conflict.body()).get("code").asString());db.update("DELETE FROM workspace_members WHERE workspace_id=? AND account_id=?",space,sender);var denied=client.request("GET",path+"/batches/"+body.get("id").asString(),null,false);assertEquals(404,denied.statusCode());assertFalse(denied.body().contains("请核对"));assertEquals(404,client.request("POST",path+"/batches",input,true).statusCode());}

}
